// Validate the fetched response before parsing: a failed or truncated fetch must never become an observation.
const i = $json;
if (i.fetchError) throw new Error(`feed-unavailable: ${String(i.fetchError).slice(0, 300)}`);
if (i.httpStatus !== 200) throw new Error(`feed-unavailable: feed returned HTTP ${i.httpStatus}`);
if (typeof i.body !== 'string' || i.body.length === 0) throw new Error('invalid-feed: empty response');
if (i.body.length > 5000000) throw new Error('invalid-feed: feed is too large');
return [{ json: { feedXml: i.body } }];

// Normalise RSS items to the experiment's feed identity (same rules as the Mastra track, #919).
const input = $('Feed input').first().json;
const host = input.publicationHost;
const publication = host.split('.')[0];
const crypto = require('crypto');
const channel = $json.rss && $json.rss.channel;
if (!channel || typeof channel !== 'object') throw new Error('invalid-feed: not an RSS channel');
const raw = channel.item === undefined ? [] : Array.isArray(channel.item) ? channel.item : [channel.item];
// A larger feed is refused rather than truncated, so a baseline never silently omits items.
if (raw.length > 500) throw new Error('invalid-feed: feed has more than 500 items');
const text = (v) => (v == null ? '' : typeof v === 'object' ? String(v._ ?? '') : String(v));
const seen = new Set();
const items = [];
for (const it of raw) {
  let url;
  try { url = new URL(text(it.link).trim()); } catch { throw new Error('invalid-feed: item link is not a URL'); }
  const m = /^\/p\/([a-z0-9-]{1,200})\/?$/.exec(url.pathname);
  if (url.protocol !== 'https:' || url.hostname !== host || url.username || url.password || !m)
    throw new Error('wrong-publication: item is not a post on the allowed publication');
  const slug = m[1];
  const canonicalUrl = `https://${host}/p/${slug}`;
  if (seen.has(canonicalUrl)) continue; // first occurrence wins
  seen.add(canonicalUrl);
  const enc = it.enclosure && typeof it.enclosure === 'object' ? it.enclosure : null;
  const enclosureUrl = enc ? String(enc.url ?? '') : '';
  const type = enc ? String(enc.type ?? '') : '';
  const postId = (/^https:\/\/api\.substack\.com\/feed\/podcast\/(\d{1,15})\//.exec(enclosureUrl) || [])[1] ?? null;
  const medium = type.startsWith('audio/') ? 'audio' : type.startsWith('video/') ? 'video' : enc ? 'unknown' : 'written';
  const d = it.pubDate ? new Date(text(it.pubDate)) : null;
  const item = {
    canonicalUrl, slug, postId,
    sourceItem: postId ? `substack:${publication}:${postId}` : null,
    title: text(it.title).trim().slice(0, 500),
    publishedAt: d && !Number.isNaN(d.getTime()) ? d.toISOString() : null,
    medium,
  };
  item.fingerprint = 'sha256:' + crypto.createHash('sha256')
    .update(JSON.stringify([item.canonicalUrl, item.postId, item.title, item.publishedAt, item.medium, enclosureUrl, text(it.description), text(it['content:encoded'])]))
    .digest('hex');
  items.push(item);
}
return [{ json: { ...input, body: undefined, items } }];

// Collect the failure of any stage, so it is recorded as a failed poll and the run ends in error.
const input = $('Feed input').first().json;
const message = String($json.error?.message ?? $json.error ?? 'unknown failure').slice(0, 1000);
return [{ json: { subscription: input.subscription, pollId: input.pollId, startedAt: input.startedAt, httpStatus: input.httpStatus ?? null, error: message } }];
